    (function () {
      var root = document.getElementById('schedule');
      if (!root) { return; }
      var tabs = Array.prototype.slice.call(root.querySelectorAll('.j2-daytab'));
      var panels = Array.prototype.slice.call(root.querySelectorAll('.j2-day'));
      if (!tabs.length || tabs.length !== panels.length) { return; }

      function show(index, focusTab) {
        tabs.forEach(function (tab, i) {
          var on = i === index;
          tab.setAttribute('aria-selected', on ? 'true' : 'false');
          tab.setAttribute('tabindex', on ? '0' : '-1');
          if (on && focusTab) { tab.focus(); }
        });
        panels.forEach(function (panel, i) {
          if (i === index) { panel.removeAttribute('hidden'); }
          else { panel.setAttribute('hidden', ''); }
        });
      }

      tabs.forEach(function (tab, i) {
        tab.addEventListener('click', function () { show(i, false); });
        tab.addEventListener('keydown', function (e) {
          var next = null;
          if (e.key === 'ArrowRight') { next = (i + 1) % tabs.length; }
          else if (e.key === 'ArrowLeft') { next = (i - 1 + tabs.length) % tabs.length; }
          if (next !== null) { e.preventDefault(); show(next, true); }
        });
      });

      show(0, false);
    })();
